-- Правила формирования урока (принципы легенды экспорта) — раньше жили
-- захардкоженным списком PRINCIPLES в lessonSchema.js, править их мог
-- только тот, кто правит код. Теперь админ добавляет/правит/удаляет их
-- прямо в редакторе (LessonRulesPanel.jsx), а buildLegend() подтягивает
-- актуальный активный список и кладёт его в экспорт урока — так модель,
-- которая видит только JSON, всегда получает текущие правила, а не те,
-- что были на момент последнего релиза кода.

create table if not exists public.lesson_rules (
  id         uuid        primary key default gen_random_uuid(),
  rule_text  text        not null,
  sort_order integer     not null default 0,
  active     boolean     not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists lesson_rules_sort_order_idx
  on public.lesson_rules (sort_order);

alter table public.lesson_rules enable row level security;

-- Админский инструмент: и читает, и пишет только админ (та же проверка,
-- что у table_templates/app_settings/races/push_templates).
drop policy if exists lesson_rules_admin_all on public.lesson_rules;
create policy lesson_rules_admin_all
  on public.lesson_rules
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Разовый посев текущих 17 принципов из lessonSchema.js — чтобы после
-- миграции список не был пустым, а редактор сразу показывал то, что уже
-- действует. Guard на "таблица пуста" — при повторном запуске миграции
-- (или если админ уже успел всё удалить) посев не повторится.
insert into public.lesson_rules (rule_text, sort_order)
select * from (values
  ('Один урок = одно целевое слово (обычно глагол). Весь сценарий — это разбор ЕГО форм, времён и употреблений; само слово не меняется от ноды к ноде.', 10),
  ('При этом всё ВОКРУГ целевого слова должно быть разным: дополнения, обстоятельства, ситуации, еда, время действия. Не повторяй одно и то же слово-дополнение (например «again», «pizza») в разных упражнениях урока — ученик должен видеть новый пример, а не тот же самый с другим местоимением. Перед сдачей урока — явно выпиши финальное/ключевое слово КАЖДОГО упражнения (answer, words, options) одним списком по порядку и проверь его на повторы: одинаковое дополнение у двух местоимений подряд внутри одного грамматического блока (например «he tries again» и «she tries again» в блоке he/she/it) — тот же самый анти-паттерн, что и повтор через весь урок, просто в меньшем масштабе.', 20),
  ('replyToSeq (цитата в чате) — ТОЛЬКО на seq МЕНЬШЕ текущего, то есть на уже прозвучавшее сообщение. Ссылка вперёд — ошибка: в момент показа этой ноды более позднего сообщения в чате ещё нет.', 30),
  ('Ученик не говорит вслух, а собирает фразу из слов — формулировки заданий должны это отражать: «Как сказать по-английски ...», «Собери фразу ...», а не «Скажи ...».', 40),
  ('Пол ученика неизвестен — избегай форм, которые его выдают («справился», «заметил», «я и не сомневался»). Используй безродные: «получилось», «вышло», «точно», «в точку», «ну конечно».', 50),
  ('После верного ответа собранная фраза уже видна в чате справа — реакции (эмодзи) для этого ОБЫЧНО ДОСТАТОЧНО, следующая нода не нужна вовсе. Добавляй текстовую ноду ПОСЛЕ реакции только если она несёт НОВУЮ мысль — объясняет «почему» (грамматику), даёт контраст с другой формой или вводит новое слово. Простой пересказ/перевод уже собранной фразы («Именно так — ты пробуешь каждый день») — это НЕ разбор, а бессмысленный повтор: ученик и так видит фразу в чате и понимает, что она значит, раз сам её собрал.', 60),
  ('Реакции на ответ чередуй: reaction (эмодзи) — самое частое; text с эмодзи — реплика; sticker — редко, для узловых моментов. Два одинаковых средства подряд читаются как автоответчик.', 70),
  ('Длинный текст (примерно от 120 знаков, больше одной-двух коротких фраз) — это всегда audio, а не text: text читается глазами и не должен выглядеть простынёй.', 80),
  ('hardWrap включай, когда текст перечисляет или подытоживает — каждая пара «форма — что значит» на своей строке.', 90),
  ('Раскраска: цвет всегда идёт вместе с bold — это два отдельных highlight на один и тот же диапазон (mode: text/bg + mode: bold). Подчёркнутое — тоже обязательно bold.', 100),
  ('Если объясняешь замену буквы внутри слова (y → i, удвоение согласной и т.п.) — нужны ОБЕ пометки, у них разные задачи. 1) Буква внутри реального слова-примера (try → tries, stop → stopped) получает mode: bg, pin: true на один-два символа («y» в try, «pp» в stopped) — готовая плашка (заливка цветом слова + тёмная буква поверх + правильный отступ до соседей), калибровка вручную по слайдерам, не считать вручную. Обязательно добавь ВТОРОЙ highlight mode: text, color: «#12140d» на тот же диапазон — иначе буква сольётся с заливкой (без него видно только цветной прямоугольник, буквы не видно). Если слово ещё и underline (типа tries) — разбей его подчёркивание на два куска В ОБХОД буквы с pin (например tries: underline 0-2 и 3-5 вокруг «i», без underline под самой «i»), иначе линия перечёркивает плашку. 2) Отдельные упоминания той же буквы в прозе объяснения («...на согласную и y...», «то y превращается...») получают mode: bold БЕЗ цвета (color можно не задавать) — просто жирным, обычным цветом текста: латинскую «y»/«i» без всякого акцента легко принять за кириллическую «у»/«и», а жирность выделяет её как отдельный символ, не добавляя цветового шума (насыщенный цвет на нескольких словах подряд читается как «слишком много выделений»).', 110),
  ('Перед сдачей — сверь каждый Русский промпт («Как сказать по-английски...», подпись фото, реплика перед dictator-таблицей) с РЕАЛЬНЫМ ответом упражнения (answer/words/script), который идёт следом. Это разные поля, их легко рассинхронизировать при правке: если поменял английский ответ ради разнообразия (например «pizza» → «cake»), а промпт перед ним не тронул — ученику дают перевести одно, а проверяют другое. Симптом: перевод в промпте не имеет ничего общего со словом в ответе.', 120),
  ('table в режиме dictator НЕ немая: голос диктует её вслух, и по ходу озвучки в таблице подсвечиваются те самые ячейки, которые в этот момент называются (timeline это и делает). Поэтому у КАЖДОЙ dictator-таблицы поле script обязательно — и оно должно звучать как живая речь учителя, а НЕ как сухое перечисление ячеек через тире. ✗ «Местоимения … I … you, we, they … Настоящее время … try» (это просто названия ячеек одна за другой, без единой мысли). ✓ «В настоящем времени мы имеем форму try» (коротко, но по-человечески — и всё равно ложится на ту же подсветку). script — часть самого урока (в отличие от note, которую видит только редактор).', 130),
  ('Таблицу с подсказкой правила показывай, когда разбираешь правило; убирай её, когда проверяешь, усвоено ли оно — иначе таблица решает задание за ученика.', 140),
  ('В каждом смысловом блоке должно быть хотя бы одно задание НА СЛУХ — фраза только голосом, без письменного текста. Без этого урок тренирует чтение, а не понимание речи.', 150),
  ('Счётная похвала («три из трёх», «ни одной ошибки») — это утверждение о ПУТИ. Ставь её только на ветке, где все ответы были верными; ветки ошибок должны вести к нейтральной реплике («вся группа разобрана»), которая верна при любом пути.', 160),
  ('Если ноде (photo/sticker/photo_choice) нужна картинка — описание для генерации пишется ТОЛЬКО в поле imagePrompt (у photo_choice — imagePrompt внутри каждого элемента photos), никогда в note. note — заметка для редактора, генерация его не читает вообще; текст в note остаётся невидимым для «🎨 Сгенерировать» и просто теряется. Если у тебя уже есть описание сцены в note — перенеси его в imagePrompt, а не дублируй в оба поля.', 170)
) as seed(rule_text, sort_order)
where not exists (select 1 from public.lesson_rules);
